<?php
namespace App\Http\Controllers; use App\Models\MembershipCategory; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class CategoryController extends Controller { public function index(){return view('categories.index',['categories'=>MembershipCategory::withCount('members')->paginate(12)]);} public function create(){return view('categories.form',['category'=>new MembershipCategory(['is_active'=>true])]);} public function store(Request $r){MembershipCategory::create($r->validate(['name'=>'required|max:100|unique:membership_categories','description'=>'nullable','is_active'=>'boolean']));return redirect()->route('categories.index')->with('success','Category created.');} public function edit(MembershipCategory $category){return view('categories.form',compact('category'));} public function update(Request $r,MembershipCategory $category){$category->update($r->validate(['name'=>['required','max:100',Rule::unique('membership_categories','name')->ignore($category)],'description'=>'nullable','is_active'=>'boolean']));return redirect()->route('categories.index')->with('success','Category updated.');} public function destroy(MembershipCategory $category){if($category->members()->exists())return back()->with('error','A category assigned to members cannot be deleted.');$category->delete();return back()->with('success','Category deleted.');} }
